// This test deletes a component before the test is run. The component
// assigned itself to a domain without schedule, which creates the
// schedule and adds the domain to the common domain. Phasing must not
// refer to the deleted component nor to memory owned by it.

#include <systemc>
#include <uvm>

using namespace uvm;
using namespace sc_core;

class leaf : public uvm_component
{
 public:
  UVM_COMPONENT_UTILS(leaf);

  leaf( uvm_component_name name ) : uvm_component(name) {}

  void main_phase(uvm_phase& phase)
  {
    phase.raise_objection(this);
    UVM_INFO("main", "Starting main", UVM_NONE);
    sc_core::wait(10, SC_SEC);
    UVM_INFO("main", "Ending main", UVM_NONE);
    phase.drop_objection(this);
  }
};

class test : public uvm_component
{
 public:
  leaf* tmp;
  leaf* keep;
  uvm_domain domain1, domain2;
  UVM_COMPONENT_UTILS(test);

  test( uvm_component_name name )
  : uvm_component(name), domain1("domain1"), domain2("domain2")
  {
    tmp = new leaf("tmp");
    tmp->set_domain(domain1); // creates schedule in domain1
    delete tmp;

    keep = new leaf("keep");
    keep->set_domain(domain2);
  }

  ~test() { delete keep; }

  void report_phase(uvm_phase& phase)
  {
    if (get_num_children() == 1 && has_child("keep") && !has_child("tmp"))
      std::cout << "*** UVM TEST PASSED ***" << std::endl;
    else
      std::cout << "*** UVM TEST FAILED ***" << std::endl;
  }
};

int sc_main(int, char*[])
{
  test* t = new test("test1");
  run_test();
  delete t;
  return 0;
}
